const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const subject = 'Re: High Priority: Onboarding Equipment Setup Needed — Tracking Confirmed';
const from = 'priya.it.lead@company.com';
const to = 'ethan.it.specialist@company.com';
const content = \`Hello Ethan,

I wanted to confirm that the onboarding equipment setup for the new contractor is now being actively tracked and scheduled for completion before their start date (start of business, 2026-09-09).

Here is the checklist we are tracking:
- Standard Windows laptop — provisioned and configured
- VPN access — set up and tested
- Email account — configured and verified

A calendar event has been created for this afternoon (2026-09-08, 2:00–4:00 PM) to ensure all items are finalized today. Please make sure each task is completed and verified before end of business today so the contractor is fully ready to go tomorrow morning.

If you run into any blockers or need additional resources, please reach out immediately.

Best,
Priya\`;

const stmt = db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

// Insert into recipient's inbox (ethan)
stmt.run(
  'ethan.it.specialist/' + subject + '.eml',
  'priya.it.lead',
  from, to, subject, content,
  'ethan.it.specialist'
);

// Insert into sender's inbox (priya)
stmt.run(
  'priya.it.lead/' + subject + '.eml',
  'priya.it.lead',
  from, to, subject, content,
  'priya.it.lead'
);

// Verify both rows
const rows = db.prepare(\"SELECT * FROM ob_emails WHERE subject LIKE '%Tracking Confirmed%'\").all();
for (const r of rows) console.log(JSON.stringify(r, null, 2));
"
